import{_ as e,a as i,b as a,c as o,d as n}from"./chunks/en_m_prihlas_azure.BR14fm0d.js";import{_ as s,a as r}from"./chunks/m_qr_ios.BHk-vJJO.js";import{_ as l,o as c,c as d,aa as p}from"./chunks/framework.BAs_AphD.js";const g="/buildary-help-preview/media/cs/diary/konec_m_mu.png",h="/buildary-help-preview/media/cs/diary/nova_app.png",k=JSON.parse('{"title":"Getting Started with the Mobile Application","description":"","frontmatter":{"title":"Getting Started with the Mobile Application","wiki":"en:tickets:m_firststeps"},"headers":[],"relativePath":"en/tickets/m_firststeps.md","filePath":"en/tickets/m_firststeps.md","lastUpdated":1794388980000}'),u={name:"en/tickets/m_firststeps.md"};function m(f,t,b,y,w,_){return c(),d("div",null,[...t[0]||(t[0]=[p('<h1 id="getting-started-with-the-mobile-application" tabindex="-1">Getting Started with the Mobile Application <a class="header-anchor" href="#getting-started-with-the-mobile-application" aria-label="Permalink to &quot;Getting Started with the Mobile Application&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><figure class="shot" style="--w:100px;"><img src="'+g+'" alt="Discontinued Ticket Management app" width="80" data-no-zoom loading="lazy"></figure><figure class="shot" style="--w:100px;"><img src="'+h+'" alt="New Buildary app" width="80" data-no-zoom loading="lazy"></figure><p>**!!! ATTENTION !!! ATTENTION !!! ATTENTION !!! ATTENTION !!! ATTENTION !!!</p><p>☚ This application will be discontinued with the release of the new version of Buildary, marking the end of the standalone mobile application for the Ticket Management module.</p><p>THE PROJECT DIARY AND TICKET MANAGEMENT MODULES ARE NOW AVAILABLE IN A SINGLE APPLICATION! ☛**</p></div><figure class="shot" style="--w:200px;"><img src="'+e+'" alt="" width="180" data-no-zoom loading="lazy"></figure><p><strong>The Buildary.online mobile application is designed for creating and viewing daily entries in the Project Diary, as well as for creating and editing tasks.</strong> It will become your great helper <strong>directly on the construction site</strong>. Its purpose is not to replace the full range of functionality available in the Buildary.online web application.</p><p>We recommend using the mobile application only after you have <strong>configured the construction site and Project Diary/Diaries in the Buildary web application</strong>.</p><p><strong>THE OPERATIONS LISTED BELOW <strong>CANNOT</strong> be performed through the mobile application and must always be carried out in the web application at www.buildary.online</strong>:</p><ul><li>creating a user account</li><li>creating and configuring a construction site, including drawings</li><li>adding participants to the construction site and members of the project team, and setting their permissions</li><li>creating and configuring Project Diaries</li><li>defining rules for assigning task assignees and approvers</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><strong>If you forget your login credentials</strong>, you also need to switch to the web interface - the login form there contains a link for resetting a forgotten password</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The application supports light / dark mode and automatically adapts to your phone&#39;s settings.</p></div><h2 id="getting-the-android-mobile-application" tabindex="-1">Getting the Android Mobile Application <a class="header-anchor" href="#getting-the-android-mobile-application" aria-label="Permalink to &quot;Getting the Android Mobile Application&quot;">​</a></h2><figure class="shot" style="--w:300px;"><img src="'+i+'" alt="" width="280" loading="lazy"></figure><figure class="shot" style="--w:150px;"><img src="'+s+'" alt="" width="120" loading="lazy"></figure><p><strong>QR code for downloading the Android application</strong></p><p><strong>The application</strong> is freely available for download from the Google Play Store under the name <strong>Buildary.Online</strong>.</p><p>The mobile application is available for devices running Android 10.0 and higher. If you have a device with an incompatible version of Android, the application will not be displayed in the Google Play Store.</p><h2 id="getting-the-ios-mobile-application" tabindex="-1">Getting the iOS Mobile Application <a class="header-anchor" href="#getting-the-ios-mobile-application" aria-label="Permalink to &quot;Getting the iOS Mobile Application&quot;">​</a></h2><figure class="shot" style="--w:300px;"><img src="'+a+'" alt="" width="280" loading="lazy"></figure><figure class="shot" style="--w:150px;"><img src="'+r+'" alt="" width="120" loading="lazy"></figure><p><strong>QR code for downloading the iOS application</strong></p><p><strong>The application</strong> is freely available for download from the App Store under the name <strong>Buildary Online</strong>.</p><p>The mobile application is available for devices running iOS 15 and higher.</p><h2 id="logging-in-to-the-application" tabindex="-1">Logging in to the Application <a class="header-anchor" href="#logging-in-to-the-application" aria-label="Permalink to &quot;Logging in to the Application&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You need to log in to the application once every 30 days. On subsequent launches, the user will be logged in automatically (provided they remained logged in and did not log out).</p></div><h3 id="_1-user-does-not-have-an-account" tabindex="-1">1/ User does not have an account <a class="header-anchor" href="#_1-user-does-not-have-an-account" aria-label="Permalink to &quot;1/ User does not have an account&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>To create and activate an account, you need to use the web interface of the <a href="https://app.buildary.online/" target="_blank" rel="noreferrer">Buildary</a> application. Registration is described in the chapter <a href="/buildary-help-preview/en/firstofall/access">Access to the Program</a>.</p></div><h3 id="_2-user-has-an-account-and-logs-in-using-an-email-address-and-password" tabindex="-1">2/ User has an account and logs in using an email address and password <a class="header-anchor" href="#_2-user-has-an-account-and-logs-in-using-an-email-address-and-password" aria-label="Permalink to &quot;2/ User has an account and logs in using an email address and password&quot;">​</a></h3><figure class="shot" style="--w:200px;"><img src="'+o+'" alt="" width="150" loading="lazy"></figure><ul><li>When the application is launched for the first time, the welcome screen with the <strong>Log in to the application</strong> button is displayed.</li><li>After pressing the button, the <strong>First Account</strong> login screen opens, where the user enters their <strong>login email address and password</strong> and confirms them by selecting <strong>Log in</strong>.</li><li>After a successful login, a list of construction sites the user has access to is displayed, allowing them to select the required construction site.</li><li>On each subsequent launch, the page corresponding to the user&#39;s last activity is displayed, either the last viewed Project Diary or the task list.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If incorrect login credentials are entered <strong>3 times in a row</strong>, the account will be <strong>temporarily locked/blocked</strong>. This block is time-limited, and login credentials can be entered again after 10 minutes. If you do not remember your credentials, go to the <strong>web interface</strong> and click &quot;Forgot my password&quot; in the Buildary login form.</p></div><h3 id="_3-user-has-an-account-and-logs-in-using-azure-ad" tabindex="-1">3/ User has an account and logs in using Azure AD <a class="header-anchor" href="#_3-user-has-an-account-and-logs-in-using-azure-ad" aria-label="Permalink to &quot;3/ User has an account and logs in using Azure AD&quot;">​</a></h3><figure class="shot" style="--w:200px;"><img src="'+n+'" alt="" width="150" loading="lazy"></figure><ul><li>When the application is launched for the first time, the welcome screen with the <strong>Log in to the application</strong> button is displayed.</li><li>After pressing the button, the <strong>First Account</strong> login screen opens.</li><li>Nothing needs to be entered, simply select <strong>Log in with Azure AD</strong>.</li><li>The user is logged in automatically, or may be prompted to enter their Microsoft account credentials.</li><li>After a successful login, a list of construction sites the user has access to is displayed, allowing them to select the required construction site.</li><li>On each subsequent launch, the page corresponding to the user&#39;s last activity is displayed, either the last viewed Project Diary or the task list.</li></ul>',32)])])}const N=l(u,[["render",m]]);export{k as __pageData,N as default};
